import Foundation
import KwipMLCore

/// Reading for current Train workflows; historical recipe exercises keep their own records.
@MainActor enum TrainingTopicLessonCopy {
    static let manualIDs:Set<String> = ["mixture-experts","train-data-access","fine-tuning","load-model","save-model","iteration-transfer","text-generation","tensorflow","sklearn","parallel","holdout","checkpoint-examples","program-export","checkpoint-lifecycle"]
    static func steps(_ id:String,operation:String?=nil)->[LessonContentStep]? {
        if let operation {
            if let task=ProgramExportLearningTask(rawValue:operation) {
                return assessment(intro:"A saved model can be useful outside the app. This exercise saves its calculation as an executable program, reloads it and checks which input sizes it accepts. Saving an executable calculation is different from saving a weights file.",data:"The checker supplies a completed model and real example rows with two measurements per observation. Batch size counts observations; changing it must not change the two-measurement sample contract. This is a dedicated artifact exercise, not an ordinary canvas training run.",controls:task.controlInstructions,meaning:ProgramExportLearningTask.captureControlExplanation,question:"What must stay fixed when a batch grows? Why is an accepted size range different from accepting arbitrary sample shapes? The original saved model must remain unchanged.")
            }
            if let task=CheckpointLearningTask(rawValue:operation) {
                if id=="checkpoint-examples" {return checkpointWorked(task)}
                return assessment(intro:"Training can take time, so a saved run should be reusable. Weights are the numbers the model learned. A checkpoint can also retain optimizer memory, random state and the number of completed training passes.",data:task.explanation+" The checker supplies the architecture, aligned rows and saved parent. These are dedicated controls; do not place a recipe node or enter a file path.",controls:task.controlInstructions,meaning:"Fine-tune weights starts a new training job using earlier weights. Exact resume continues the earlier job and must retain compatible data, batching and training state. Target total epochs includes passes already completed.",question:"Does the chosen mode start fresh optimizer memory or continue it? If two epochs are complete and the total target is four, how many more passes are required? Why must the parent's bytes remain unchanged?")
            }
            return nil
        }
        if let entry=LearnCatalogContent.componentExampleEntries.first(where:{$0.componentID==id && $0.item.category=="Training & evaluation"}) {return bundled(id,learning:entry.learning)}
        switch id {
        case "train-data-access":
            return practice(intro:"A training row pairs input measurements with the answer the model should learn. This practice uses 64 synthetic observations: signal and context are numeric measurements; label is the desired category. Partition reserves 32 Training, 16 Validation and 16 Test rows. Preprocess learns scaling from Training alone.",launch:"Open Train data access practice in Exercise choices & reference. Its model predicts two class scores from signal and context. Follow the Training and Validation table connections into Train. Model definition supplies the calculation; Train owns column mapping, data access and batches.",actions:TrainDataAccessLessonContent.steps,question:"What changes when you choose three training positions: the Training observations, the model's feature order, or Validation? Why does dropping an incomplete batch leave source data intact?",boundary:TrainDataAccessLessonContent.boundary)
        case "mixture-experts":
            return practice(intro:"This canvas learns two class scores from the two measurements in each observation. Feature mixture contains four small independent networks called experts. A learned router chooses two for each observation and combines their outputs. The experts are not preassigned topics: training may produce useful differences, but balanced traffic alone does not prove specialization.",launch:"Open this practice. Observation features enters Feature mixture, then Class scores exposes the combined result to Train. Partition keeps the Validation population separate. Expand Feature mixture on the main canvas. Each named row holds one expert’s actual layers. The container’s input binds to each first layer and each final layer returns to its combined output. Configure mixture holds the router architecture, routing and capture settings.",actions:["Inside the Feature mixture container, find the Expert B row and follow its Linear → GELU → Linear chain. Select a layer to use the normal Configuration controls. Each expert accepts two measurements and returns two scores here; hidden widths may differ. Undo reverses a canvas edit. Keep wires inside their own expert chain; the container performs routing and combines the selected outputs. Dashed rose boundary links show this routed input and weighted combination; ordinary layer wires stay teal.","In Routing keep two experts per unit and normalized selected weights. Router layers shows the actual input, gate and expert-score boundary; select a layer to read its connections and edit its normal fields. Advanced router JSON is optional for topology changes. Temperature changes probability sharpness. Try one expert only later: normalized top-1 gives the gate no task-loss gradient, so inspect the explicit balancing controls rather than assuming it learns from class loss.","Choose Validate to check synthetic CPU values and gradients without updating weights, then Apply. Select Train to choose the usual optimizer, epochs and device. Run Flow trains through the actual selected experts. All expert weights remain in memory, even when fewer execute for an observation. An unselected expert should not move from stale gradients or weight decay.","In Train Metrics choose MoE objective to inspect Task loss, Balance penalty, Router z penalty and their sum during completed reporting intervals. Best Validation continues to use the task metric. Compare with a dense baseline on the same held-out observations; neither balance nor a low training objective guarantees better predictions.","In Train Output choose Routing summary. This is the normal paged table: assignments count expert visits, and shares use all assignments as their denominator. One observation may visit two experts; repeated epochs count again. Connect the routing table port to View or Table Output when you need its rows downstream.","Enable Aggregate + bounded unit sample only when needed. Samples contain routing identities and weights, not raw source documents. Off or disabled History diagnostic retention means Not captured. History reads the saved evidence without rerunning training. Save model retains all experts and router; a native canvas-model package is not a generic Hugging Face MoE architecture."],question:"Why can top-2 use fewer expert calculations while still keeping all expert weights resident? What would you compare to show that a routed model actually improves the task?",boundary:"This practice checks an editable small routed classifier. It does not load a large pretrained MoE or prove that experts have learned human topic labels.")
        case "fine-tuning":
            return practice(intro:"Fine-tuning changes a model's learned numbers using new examples. This practice starts with a verified GPT-2 or Llama causal model and eight short synthetic documents. Each token is trained to predict the following token. Partition keeps Validation documents separate from Training.",launch:"Open fine-tuning practice. Select Choose a causal language model and choose a supported local folder, or explicitly download a supported pinned snapshot in Load model. No model is downloaded automatically. The Model wire carries verified architecture and weights; both table wires carry documents.",actions:["Select Adapt the loaded model and open Configure fine-tuning. The seven sections edit one draft. In Data & loss keep Full-text language modeling and Text column text for these supplied documents. Context is the maximum tokens in one window; stride advances inside that document. Windows never join documents. Append end-of-sequence uses this model’s matching tokenizer.","For your own prompt/response table, choose Prompt + response and two String columns. Choose an explicit separator and Response tokens only when the model should learn the answer while reading the prompt. Prompt and padding positions are excluded from loss. Overlong responses are refused rather than silently removed. Validate & inspect displays a bounded first token window and checks a real forward/backward pass without updating weights. This explicit inspection can reveal training text; it is not a sample used to choose training rows.","In Trainable weights choose Full model, Selected layers or LoRA adapter. Search the actual groups or projection inventory. Linked embeddings stay linked. LoRA rank controls the learned low-rank width; alpha scales it and dropout applies during training. Additional modules must be independent of both tied groups and adapter targets. Validate checks the actual trainable count and memory allowance.","Keep the supplied run at one CPU epoch, batch size two and context eight. Optimization reuses shared optimizer and schedule settings. Validation & selection separates Best Validation inference weights from the latest resume boundary. Compute & limits offers activation recomputation to trade extra backward work for activation memory; this is different from saving checkpoints. Apply saves the validated draft; Run Flow starts training.","Before running, select Save the updated model and choose an unused destination. Run Flow trains once, then generates text and saves the selected standalone model. Inspect completed-batch loss and measured Validation in Metrics. Predictions and generated text use standard Output tables. To score a held-out population, connect the trained Model and Partition’s Test or Validation table to Evaluate. Evaluation inherits Train’s text/loss mapping, performs no updates and records local exposure. It reports token-weighted loss and perplexity, not classification accuracy.","In Resume & retention, zero completed boundaries keeps the legacy terminal-only behavior. A positive count and byte allowance retain atomic completed epochs. Pause after completed epoch finishes the current epoch and still supplies selected inference weights. Stop now does not complete the run; only already committed retained epochs can recover. Exact CPU resume needs matching base, tokenizer, data, settings, runtime and original schedule horizon. MPS supports weights reuse with fresh optimizer memory, not exact resume.","Save model’s expanded editor distinguishes Standalone inference model, Adapter + base identity and CPU Training resume package. Standalone LoRA saves merged weights; adapter export needs its exact local base; a resume package retains the latest optimizer, scheduler and RNG state. Raw documents are not included. Import a CPU resume package from Train, connect the matching base and retain the original Training/Validation data. Choose a new folder for every export. Training Code can replay the captured task with explicit external model, data, resource and optional resume-package bindings; whole-flow Generate/Save/Evaluate replay is still refused rather than omitted."],question:"What changes during fine-tuning: tokenizer IDs, learned weights, or the held-out documents? Why does an adapter need its exact base? Why must the selected best model and latest optimizer state be treated separately?",boundary:"This practice is unscored. Reviewed GPT-2/Llama causal adapters support float32 CPU/MPS training; quantized training and arbitrary repository code remain unsupported. For Laya’s CPU typed-decision task, open Train typed decisions for support tickets. A tiny synthetic run proves mechanics, not language quality.")
        case "load-model":
            return practice(intro:"A model needs both its learned weights and the rules that turn text into token IDs. Load model reuses a verified saved run, or imports a local model folder or a pinned Hugging Face snapshot. Loading does not train the model. This supplied canvas demonstrates causal text generation. Load model also supports task-specific adapters: Whisper for transcription, AST for sound classification and Laya for typed decisions. Prebuilt / document model package imports fitted classical models. Each needs its own matching processor and consumer; loading one does not enable every operation.",launch:"Choose Open text generation practice in Exercise choices & reference. Run its small synthetic model first. Add Load model and keep Source set to Saved run to select that completed result in Configuration. Connect its model output to Continue a prompt.",actions:["For this causal-text exercise, choose Local folder and select a supported GPT-2 or Llama folder containing config.json, tokenizer.json and safetensors weights. Load and verify copies a private snapshot; the original folder remains unchanged. Unsupported architectures, repository code and pickle weights are refused.","For Hugging Face, enter organization/model and a branch, tag or commit. Resolve the snapshot, inspect its bounded file list and download explicitly. The selected snapshot is pinned to an immutable commit. A private repository uses a named credential stored separately in Keychain.","Inspect the verified model signature and tokenizer. Maximum tokens counts token positions, not characters. Reject long text preserves an explicit error; Truncate discards excess tokens. Padding adds positions and an attention mask marks real tokens. Preview a short sample and compare Position, Token, ID and Mask.","Connect Continue a prompt, apply its prompt and choose Generate. Inspect the captured output table. Save model can write an imported model as a Hugging Face folder with safe weights, the matching tokenizer and provenance. Choose an unused destination and a shard size; sharding changes storage layout, not model values."],question:"Why must a model keep its matching tokenizer? How does a pinned commit differ from following a moving branch? Does loading or generating update weights?",boundary:"Imported models currently support inspection, tokenization, bounded generation and local export. Connect a reviewed causal model to Train in Loaded model mode for full, selected-layer or LoRA training. For other tasks, open Transcribe a private recording, Classify sounds in a recording, Train typed decisions for support tickets or Explore behavior segments in the Library. Their required files and consumers differ; do not attach speech/audio models to Generate text. Publishing to the Hub remains unavailable. Model downloads are explicit and bounded to 2 GB. This practice is unscored.")
        case "save-model":
            return practice(intro:"A trained result is useful only if you can reuse it. Train's model output refers to verified learned weights; Save model writes that result to a destination you choose. The supplied classifier learns to choose between two categories from signal and context.",launch:"Choose Open classifier practice in Exercise choices & reference. Run the classifier first. Keep Table Input → preparation → Train separate from the tensor model path. The completed model output is reusable data; connecting it does not train again.",actions:["Add Save model. Connect Train's model output to its model input. For an older completed result, use Load model with Source set to Saved run and choose the run in Configuration instead.","Select Save model and choose Portable package or Checkpoint (.pt). Choose destination and use the requested macOS folder controls. Choose a new destination if one already exists; the save refuses an overwrite.","Choose Save model and inspect its actual completion status and files. A portable package includes model code, learned weights and an input contract; provide already-prepared observations in that order. It does not silently export fitted preprocessing.","A checkpoint retains captured model/training state where recorded; it is not a standalone inference program. To inspect prediction quality, connect the verified model to Evaluate with the matching archived Validation or Test table. Evaluation never updates weights."],question:"Which saved format includes prediction code? Why must new input columns retain the model's expected order and preparation?",boundary:"Prepared image/audio models keep their exact tensor input contract. Reapply the explicit preparation recipe for new files; a saved checkpoint does not imply a raw-file processor. The destination stays private to this project on this Mac. Save operations preserve the recorded parent model. This unscored practice awards no assessment receipt.")
        case "text-generation":
            return practice(intro:"A next-token model predicts a token after the preceding tokens. This practice uses short synthetic text and a small pointwise model. Text encoding turns characters into IDs; Sequence windows aligns context with the next-token targets. Repetition here demonstrates mechanics, not language quality.",launch:"Choose Open text generation practice in Exercise choices & reference. Follow text → Text encoding → Sequence windows → Train. The model uses Embedding and learned projections; Continue a prompt receives Train's completed model and captured tokenizer.",actions:["Run Learn next-token transitions. Select Continue a prompt and choose Generate. It uses the verified completed weights without fitting vocabulary or training again. A compatible Load model in Saved run mode can provide an earlier model.","Inspect Output: text contains the completion, and new_tokens counts emitted token IDs. Inspect generated_ids for Position, Token and ID, then use Back to Output. Change the prompt to bab, Apply and generate again.","Compare Greedy with Sample. Top-k 1 behaves like greedy; temperature and wider candidate choices allow alternatives. Keep the CPU seed fixed for a controlled comparison. Each prompt has its own random stream; other devices or runtime versions can differ.","Review context and stop controls. Short prompts pad on the right but prediction uses the last real token. Long prompts refuse unless Keep latest context is explicit. Token limit bounds generation; EOS stops only when the captured tokenizer defines it. PAD and BOS are not sampled; UNK needs permission.","For Table column prompts, Apply the mode, connect a prepared String table and run its source before Generate. Stable row identities remain paired with completions. Keep prompt count × token allowance within the total budget; sample upstream if needed."],question:"Why must generation reuse the training tokenizer? Does changing temperature retrain the weights? Why does a multi-position model also need causal attention?",boundary:"Model, tokenizer, prompts and outputs remain required evidence even with optional run capture off. Cancellation/failure does not publish partial output. Whole-workflow Code currently refuses Generate text rather than omit it. This unscored practice is not a full Llama implementation or a language benchmark.")
        case "iteration-transfer":
            var result=[LessonContent.step("goal","Understand the workflow","A useful experiment changes one thing while keeping the comparison fair. This Guided lesson uses the parallel classifier: signal and context feed two learned paths, their results combine, and Train predicts a category. The data pipeline reserves checking rows and fits preparation on Training alone.\n\nUse Open parallel classifier practice in Exercise choices & reference. Open separable Block practice is an alternative for reusable architecture. Save existing edits before opening a replacement example. This Guided workflow is unscored.")]
            for topic in IterationTransferLessonContent.topics {
                result.append(.init(id:topic.id,title:topic.title,blocks:[.init(id:topic.id+".goal",kind:.explanation,title:"Understand the idea",text:topic.goal),.init(id:topic.id+".try",kind:.canvasAction,title:"Try it on the canvas",text:topic.steps.enumerated().map {"\($0.offset+1). \($0.element)"}.joined(separator:"\n")),.init(id:topic.id+".inspect",kind:.observation,title:"Read the evidence",text:topic.observation),.init(id:topic.id+".limits",kind:.detail,title:"Current limits",text:topic.limits)]))
            }
            result.append(LessonContent.step("reflect","Check your understanding","Which state should exact continuation retain? What did you hold fixed in the comparison? Save the canvas to retain your work; optional run-detail capture is separate from required trained-model and replay evidence. A saved comparison is not an automatically scored assessment.",kind:.question));return result
        case "parallel":
            return practice(intro:"Two measurements can be useful in different combinations. This classifier sends the same signal/context pair through two learned Linear paths. One uses ReLU, which keeps positive values; the other uses Tanh, which produces bounded signed values. Concatenate joins their features before a final Linear produces two class scores.",launch:"This Example opens the prepared workflow directly. Use Open example in Exercise choices & reference to reload the supplied parallel classifier after saving your work. Follow Table Input → Columns → Partition → Preprocess → Train, alongside the two-branch model path into Model definition.",actions:["Select each branch and compare declared shapes. N counts observations; a feature width counts numbers within one observation. Follow both inputs of Concatenate and predict its combined width.","Run Flow. Select a branch's captured Output, then Concatenate and the final scores. Inspect Train's predictions separately; tensor values alone do not establish correct answers.","Change one branch's feature width and adjust dependent widths as required. Apply and rerun; compare Validation under the same partition/seed. Read Diagnostics if the connected dimensions disagree."],question:"Why can two branches learn different representations of the same measurements? How does concatenation differ from adding their values?",boundary:"This runnable Example is unscored. Protected Test rows remain separate from model selection and Training-fitted preparation.")
        case "holdout":
            return practice(intro:"Rows can appear independent while sharing the same subject or future information. A random row split may then make a model look stronger than it is. These examples classify synthetic measurements while protecting whole subjects or later dated observations.",launch:"In Exercise choices & reference, choose Open subject holdout example or Open chronological example. Follow Table Input → Partition → Preprocess → classifier. The initial reference canvas is empty until you choose an example. Save existing edits before loading another.",actions:["In the subject example, inspect Partition's entity column and confirm all rows for a subject stay together. In the chronological example, inspect explicit cutoff dates and any excluded boundary rows. These are different split meanings, not interchangeable seeds.","Trace each partition into Preprocess. Only Training fits averages and spreads; Validation and Test reuse them unchanged. Check row identities and counts in captured table outputs after running.","Run Train using Training and Validation. Use its model output or select the verified saved run in Load model’s Saved run mode. Connect Evaluate to that model and the matching archived table; choose Validation for comparisons or Test for the final check."],question:"Why can holding out random rows still leak a subject? Why must the final Test population remain unused while choosing model settings?",boundary:"Evaluation reads the selected recorded population and does not update weights or fitted preparation. This Example is unscored; one protected split is not proof that every future source will generalize.")
        case "sklearn","tensorflow":return backend(id)
        case "checkpoint-examples":
            return practice(intro:"A saved run can seed a new job or continue the old one. These worked examples use a supplied small model, aligned numeric rows and a real saved parent. Weights are learned settings; optimizer memory and random state are additional information needed for exact continuation.",launch:"The initial Example canvas is empty. In Exercise choices & reference, choose one of the Save and reopen worked examples. It opens dedicated controls rather than a general canvas model. These examples are Guided/unscored; the separate Saved runs and continuation lab contains assessments.",actions:["Read the selected training behavior and parent. Fine-tune weights keeps weights and starts new training memory. Exact resume preserves the old training process.","Apply the controls, then choose Check construction. The checker creates and reloads a real saved parent and compares the measured reuse. It supplies the rows and architecture; no paths or typed answers are needed.","Inspect the measured difference tables in this public example. Zero difference means agreement for that check. Start fresh opens another prepared copy; the original edits and saved history remain available."],question:"Which mode should retain optimizer memory? Why must a successful reuse leave the parent's bytes unchanged?",boundary:"Opening or checking this unscored worked example does not award a separate assessment receipt.")
        case "program-export","checkpoint-lifecycle":
            return [LessonContent.step("goal","Understand this construction family",id=="program-export" ? "Save and reload an executable calculation, then check its declared observation-count rules. A saved calculation and a weights file serve different purposes.":"Compare reusing learned weights with continuing a saved training job. A checkpoint can retain both weights and the state of the training process."),LessonContent.step("data","Understand the supplied context","Each assessment supplies its own model, aligned numeric rows and saved parent where needed. These are dedicated controls, not an ordinary training graph. Private fixture values stay hidden."),LessonContent.step("choose","Choose an assessment","Open an individual assessment from the library row. Read its configuration directions, Apply pending changes and choose Submit assessment. The task's original identity and measured criteria remain authoritative.",kind:.canvasAction),LessonContent.step("scope","Read completion honestly","A current passing assessment saves its own receipt. The separate public worked examples are unscored and do not award this completion. Changing an assessed construction makes its previous result historical.",kind:.observation)]
        default:return nil
        }
    }
    private static func assessment(intro:String,data:String,controls:String,meaning:String,question:String)->[LessonContentStep] {
        [LessonContent.step("goal","Understand the goal",intro),LessonContent.step("data","Understand the supplied context",data),.init(id:"configure",title:"Configure this task",blocks:[.init(id:"configure.try",kind:.canvasAction,title:"Try it on the canvas",text:controls+" Apply pending changes."),.init(id:"configure.meaning",kind:.detail,title:"What the controls mean",text:meaning)]),LessonContent.step("predict","Predict before submitting",question,kind:.question),LessonContent.step("check","Submit and read the feedback","Choose Submit assessment. The checker measures independent inputs and the actual save/reload operation. Private fixture rows and reference tables remain hidden. Read the criterion's feedback to repair controls; cancellation or unavailable runtime is not a mathematical failure. A current passing assessment and saved receipt establish completion for this task, not broader mastery.",kind:.observation)]
    }
    private static func checkpointWorked(_ task:CheckpointLearningTask)->[LessonContentStep] {
        practice(intro:"This is the prepared “"+task.title+"” worked example. A small supplied model and aligned numeric rows let you inspect real saved-state reuse. It is Guided and unscored, not an assessment attempt.",launch:"The dedicated controls are already configured. Read the chosen behavior and Saved lesson run parent; no source node or file picker is needed. Start fresh opens a new prepared copy and keeps this one.",actions:[task.controlInstructions+" Apply pending changes.","Choose Check construction. Inspect the measured weights/state differences and the unchanged-parent check. These public example tables show actual execution; they are not guessed from Configuration."],question:"What does this mode reuse, and what starts over? How do you distinguish an old result from a check of your current controls?",boundary:"A formative example check does not award assessment completion. To submit a private assessment, open Saved runs and continuation lab separately.")
    }
    private static func practice(intro:String,launch:String,actions:[String],question:String,boundary:String)->[LessonContentStep] {
        var result=[LessonContent.step("goal","Meet the workflow",intro),LessonContent.step("open","Open and trace the canvas",launch,kind:.canvasAction)]
        result += actions.enumerated().map {LessonContent.step("try.\($0.offset)","Try it · \($0.offset+1)",$0.element,kind:.canvasAction)}
        result.append(.init(id:"inspect",title:"Explain the evidence",blocks:[.init(id:"inspect.question",kind:.question,title:"Check your understanding",text:question),.init(id:"inspect.boundary",kind:.detail,title:"Scope of this lesson",text:boundary+" This lesson is unscored.")]));return result
    }
    private static func backend(_ id:String)->[LessonContentStep] {
        let sklearn=id=="sklearn"
        return practice(intro:sklearn ? "Logistic regression learns a linear boundary between two categories. Signal and context are its two input measurements; label is the answer. Its probability is an estimate, not a guarantee.":"This TensorFlow/Keras classifier learns from two numeric measurements to predict two category scores. Linear combines measurements using weights and bias; ReLU keeps positive values. The final two scores are logits, not probabilities.",launch:sklearn ? "Choose Build logistic regression example in Exercise choices & reference. Follow Table Input → Columns → Partition → Preprocess → Logistic regression. Validation checks rows that did not train the model.":"Choose Build TensorFlow example in Exercise choices & reference. Follow the table preparation into Train and the model path Linear → Activation (ReLU) → Linear → Model definition. The first Linear creates eight features; the final Linear produces two scores.",actions:["Inspect Partition and the three Preprocess connections. Scaling fits Training alone and applies the same rule to Validation and Test. Keep signal then context in the input order and label as target.",sklearn ? "Select Logistic regression. Confirm First feature column, Second feature column and Target column. Apply column mapping before changing other controls. Run Flow and inspect the component's captured output and the completed History record.":"Select Keras classifier and confirm its feature/target mapping and CPU settings. Apply column mapping before changing other controls. Run Flow and inspect captured layer outputs and the completed History record. Missing optional runtime support must be resolved before there are real results.",sklearn ? "Compare Inverse regularization C = 1 with C = 0.1 while retaining the same split. Smaller C restrains large weights more strongly. Compare Validation accuracy and log loss, and read convergence warnings. Change the random partition seed on Partition, not on a retired Split node.":"Keep the partition fixed and change one training choice. Compare Validation loss and accuracy alongside configuration. Prediction with exported weights expects already-prepared float32 rows with the same two features."],question:"Why must checking rows stay out of fitted preparation? Does a good Training score guarantee a useful model on new observations?",boundary:sklearn ? "This CPU solver fits all selected training rows together; it has no neural-network batch or initialization-seed controls. This Example is unscored.":"This scoped CPU backend supports its reviewed layers and exports Keras weights for prediction. GPU and exact optimizer-state continuation are unsupported here. This Example is unscored.")
    }
    private static func bundled(_ id:String,learning:any BundledComponentLearningContent)->[LessonContentStep] {
        let optimizer=BundledOptimizerComponents.entries[id] != nil,scheduler=BundledSchedulerComponents.entries[id] != nil
        let role=optimizer ? "An optimizer uses measured gradients to adjust learned weights. Its memory can affect the next update.":scheduler ? "A learning-rate schedule changes the size of later adjustments. Its timing and remembered progress are part of continuation.":"An objective measures the difference between model outputs and the desired targets. The target's meaning and shape must fit this scoring rule."
        let area=optimizer ? "optimizer":scheduler ? "schedule":"objective"
        var result=[LessonContent.step("goal","Meet the training example",role+"\n\n"+learning.subtitle+"\n\nThis Example initially opens a reference canvas. In Exercise choices & reference choose “"+learning.buttonTitle+"” to open its supplied runnable workflow. Save existing edits before replacing it. The data pipeline prepares separate Training and Validation tables; the model produces scores or other task-specific values. Train owns mapping, the "+area+" and run settings. These settings are inline; do not add a configuration-input node."),LessonContent.step("open","Trace the actual controls","Open the supplied example. Select Train and find its "+area+" in Configuration. Follow the model and prepared table connections. Inputs are measurements; targets are the answers or comparisons used by this particular objective. Predict what changing one setting should do before running.",kind:.canvasAction)]
        result += learning.paragraphs.enumerated().map {LessonContent.step("explain.\($0.offset)","Understand the "+area+" · \($0.offset+1)",$0.element)}
        result.append(.init(id:"inspect",title:"Run and compare",blocks:[.init(id:"inspect.try",kind:.canvasAction,title:"Try it on the canvas",text:"Run Flow with the supplied settings. Inspect Train's captured predictions/output and the completed run in History. Compare recorded training behavior and Validation where this example provides it. Change one supported "+area+" setting, Apply and rerun; retain data, split and seed for a controlled comparison."),.init(id:"inspect.formula",kind:.visual,title:"Optional relationship",text:learning.formula,visual:.init(kind:.equation)),.init(id:"inspect.question",kind:.question,title:"Check your understanding",text:"Which setting changed, and which evidence was actually measured? Why is a declared configuration different from a completed update? This runnable Example is unscored; historical connected-recipe assessments retain their original records and are not restarted here.")]));return result
    }
}
